WF.uiState=function(){let _cache=null;return{load:function(){if(_cache)return _cache;try{const raw=localStorage.getItem("wf_checklist_ui_state");_cache=raw?JSON.parse(raw):{}}catch(err){WF.logs.AddLog("Unreadable or corrupted localStorage UI state, reset","error",err),_cache={}}return _cache},save:function(state){_cache=state;try{localStorage.setItem("wf_checklist_ui_state",JSON.stringify(state))}catch(err){WF.logs.AddLog("Failed to save UI state to localStorage","error",err)}},STORAGE_KEY:"wf_checklist_ui_state"}}();